input.content:
*{box-sizing:border-box}
:root{--bg:#f3f4ee;--paper:#fff;--ink:#17231d;--ink-2:#425348;--muted:#8b958d;--line:#e5e9e1;--line-soft:#eef1eb;--green:#316849;--green-deep:#1f3c2b;--lime:#cbe97a;--lime-soft:#edf4dd;--sand:#f4f1e7;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Manrope',sans-serif}
html{background:var(--bg);scroll-behavior:smooth}
body{margin:0;color:var(--ink);font-family:var(--sans);font-size:14px;-webkit-font-smoothing:antialiased}
button,input,select{font:inherit;color:inherit}
button{cursor:pointer}
a{color:inherit}
::selection{background:#dcecae;color:#1c3022}
.app{display:grid;grid-template-columns:236px minmax(0,1fr);min-height:100vh}
.sidebar{position:sticky;top:0;height:100vh;background:#fbfcf8;border-right:1px solid var(--line);padding:26px 18px 18px;display:flex;flex-direction:column;z-index:5}
.brand{display:flex;align-items:center;gap:11px;text-decoration:none;font:800 16px var(--display);letter-spacing:.13em;padding:0 6px}
.brand-mark{display:grid;place-items:center;width:35px;height:35px;border-radius:11px;background:#1f392b;color:#d4ed93;font:700 20px var(--display);letter-spacing:-.08em}
.brand-slash{color:#90bb61}
.brand-type small{display:block;color:#9aa39b;font:500 7px var(--mono);letter-spacing:.12em;margin-top:3px}
.side-label{font:500 7px var(--mono);letter-spacing:.13em;color:#a6aea6;margin:31px 8px 9px}
.side-label-spaced{margin-top:26px}
.side-nav{display:grid;gap:3px}
.nav-item{height:37px;border:0;background:transparent;border-radius:7px;display:flex;align-items:center;gap:10px;padding:0 9px;color:#718077;font:500 11.5px var(--sans);text-align:left;transition:.15s}
.nav-item:hover{background:#f1f4eb;color:#314f3c}
.nav-item.active{background:#edf2e4;color:#274b35;font-weight:600}
.nav-ico{width:16px;font-size:14px;color:#8b9c8b;text-align:center;font-family:var(--display)}
.nav-item.active .nav-ico{color:#62854f}
.nav-item em{margin-left:auto;font:8px var(--mono);font-style:normal;color:#9aa59b;background:#f0f2ed;padding:2px 5px;border-radius:3px}
.nav-item .beta,.beta{margin-left:auto;font:7px var(--mono);font-style:normal;letter-spacing:.04em;color:#7a9143;background:#eef4dd;padding:3px 5px;border-radius:3px;text-transform:uppercase}
.legal-mini{margin-top:auto;background:#f0f3e9;border:1px solid #e6ebdc;border-radius:9px;padding:12px}
.legal-mini-top{display:flex;align-items:center;gap:7px;color:#73866d;font-size:9px}
.legal-mini-top b{font-weight:600;color:#4e6650}
.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#79a94e;box-shadow:0 0 0 3px #e4eedb;flex-shrink:0}
.legal-mini-space{display:flex;align-items:center;gap:8px;margin:10px 0 8px}
.legal-mini-space strong{font:700 27px var(--display);letter-spacing:-.06em;color:#2f4d38}
.legal-mini-space span{font:8px/1.5 var(--mono);color:#829080}
.legal-mini-plants{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e3e8d9;padding-top:7px;color:#5f725f;font-size:9px}
.legal-check{color:#668c45;font-size:11px}
.legal-mini p{font-size:8px;line-height:1.5;color:#93a08d;margin:8px 0 0}
.side-user{display:flex;align-items:center;gap:9px;padding:16px 5px 2px;margin-top:12px;border-top:1px solid #eef1eb}
.avatar,.top-avatar{display:grid;place-items:center;background:#2a4734;color:#e3f0c7;border-radius:50%;width:29px;height:29px;font:600 9px var(--mono);letter-spacing:.03em}
.side-user b,.side-user small{display:block}
.side-user b{font:600 10.5px var(--display)}
.side-user small{font-size:8.5px;color:#9ca69d;margin-top:2px}
.side-user .dots{margin-left:auto;border:0;background:none;color:#a1aba2;font-size:11px;letter-spacing:1px}
.main{min-width:0;display:flex;flex-direction:column}
.topbar{height:68px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;padding:0 36px;border-bottom:1px solid var(--line);background:rgba(243,244,238,.86);backdrop-filter:blur(10px);position:sticky;top:0;z-index:4}
.crumb{font:8px var(--mono);letter-spacing:.13em;color:#a4ada4;display:flex;align-items:center;gap:9px}
.crumb i{font-style:normal;color:#ced4cc}
.crumb b{color:#5d6e61;font-weight:500}
.topbar-actions{display:flex;align-items:center;gap:9px}
.legal-pill{display:flex;align-items:center;gap:6px;background:#fff;border:1px solid var(--line);border-radius:6px;padding:6px 9px;font:7px var(--mono);letter-spacing:.08em;color:#6f7f6f}
.legal-pill .live-dot{width:5px;height:5px;box-shadow:none}
.icon-btn{width:31px;height:31px;border:1px solid var(--line);background:transparent;border-radius:7px;color:#6c7d70;font-size:14px;display:grid;place-items:center;transition:.15s}
.icon-btn:hover{background:#fff;color:#385544}
.top-avatar{width:30px;height:30px;font-size:8px;margin-left:2px}
.views{padding:30px 36px 52px;max-width:1280px;width:100%;margin:0 auto}
.view{display:none}
.view.active{display:block;animation:fade .22s ease}
@keyframes fade{from{opacity:.35;transform:translateY(3px)}to{opacity:1;transform:none}}
.view-head{display:flex;align-items:flex-end;justify-content:space-between;gap:40px;margin-bottom:26px}
.eyebrow{display:flex;align-items:center;gap:8px;color:#8b968d;font:7.5px var(--mono);letter-spacing:.12em}
.eyebrow i{font-style:normal;color:#c7cec6}
.eyebrow b{color:#5b6d5f;font-weight:500}
.view-head h1{font:600 clamp(31px,3.4vw,45px)/1.03 var(--display);letter-spacing:-.055em;margin:12px 0 9px}
.view-head h1 em{font-style:normal;color:#547a5d}
.lead{font-size:12px;line-height:1.65;color:#89958c;margin:0;max-width:590px}
.head-actions{display:flex;gap:8px;flex-shrink:0;padding-bottom:3px}
.btn{height:37px;border-radius:6px;border:1px solid transparent;padding:0 14px;font:600 10.5px var(--sans);display:inline-flex;align-items:center;gap:14px;justify-content:center;transition:.18s;white-space:nowrap}
.btn span{font-size:13px;font-weight:400}
.btn-primary{background:#2b4c36;color:#f4f8ec;box-shadow:0 3px 9px #2b4c3620}
.btn-primary:hover{background:#38664a;transform:translateY(-1px)}
.btn-ghost{background:transparent;border-color:#dfe5db;color:#536b59}
.btn-ghost:hover{background:#fff;border-color:#cdd7c7}
.btn-soft{background:#f1f5e9;border-color:#e3ead9;color:#4e6d4e}
.btn-soft:hover{background:#e8f0dc}
.btn.full{width:100%}
.text-link{border:0;background:none;color:#63805f;font:600 9.5px var(--sans);padding:0;display:inline-flex;align-items:center;gap:5px}
.text-link:hover{color:#2c583d;text-decoration:underline;text-underline-offset:3px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:10px}
.section-kicker{display:block;font:500 7px var(--mono);letter-spacing:.12em;color:#98a299;margin-bottom:3px}
.card-head{display:flex;align-items:flex-start;justify-content:space-between;padding:17px 19px 13px;gap:15px}
.card-head h2{font:650 14.5px var(--display);letter-spacing:-.025em;margin:3px 0 0}

/* ===== PANEL ===== */
.panel-head{margin-bottom:23px}
.stat-strip{display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border:1px solid var(--line);border-radius:10px;margin-bottom:16px;overflow:hidden}
.stat{display:flex;align-items:center;gap:10px;padding:15px 15px;border-right:1px solid var(--line-soft);min-width:0}
.stat:last-child{border-right:0}
.stat-ico{width:30px;height:30px;border-radius:7px;display:grid;place-items:center;background:#f4f1e7;color:#a3925c;font-size:14px;flex-shrink:0}
.stat-ico.green{background:#eef5e2;color:#6f954c}
.stat>div{min-width:0}
.stat-label{display:block;font:7px var(--mono);letter-spacing:.08em;color:#a0a9a1;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.stat b{font:700 17px/1 var(--display);letter-spacing:-.04em;display:block;white-space:nowrap}
.stat b small{font:400 8px var(--mono);color:#a6aea6;letter-spacing:0;margin-left:2px}
.stat-trend{margin-left:auto;align-self:flex-start;font:7px var(--mono);letter-spacing:.03em;color:#9ba59b;background:#f4f6f1;padding:3px 4px;border-radius:3px;white-space:nowrap}
.panel-hero-grid{display:grid;grid-template-columns:1.6fr .84fr;gap:16px;margin-bottom:16px}
.hero-grow{background:linear-gradient(135deg,#223c2c,#1b3124 60%,#192d21);border-radius:10px;color:#aebcae;padding:20px 22px 0;overflow:hidden;position:relative}
.hero-grow:after{content:'';position:absolute;width:300px;height:200px;right:-40px;top:-80px;background:#ccea7c0d;filter:blur(30px);border-radius:50%;pointer-events:none}
.hero-grow-top{display:flex;align-items:start;justify-content:space-between}
.section-kicker.light{color:#8fa28f}
.hero-grow .section-kicker{color:#8fa28f}
.hero-grow h2{font:650 21px var(--display);letter-spacing:-.035em;margin:4px 0 0;color:#f1f6e8}
.phase-pill{display:inline-block;background:#eef4df;color:#64823e;padding:5px 8px;border-radius:4px;font:500 7px var(--mono);letter-spacing:.06em;white-space:nowrap}
.hero-grow .phase-pill{background:#314a38;color:#d8e9b8;padding:6px 8px}
.hero-grow-copy{font-size:10.5px;line-height:1.6;color:#94a795;margin:9px 0 14px;max-width:480px}
.hero-mini{height:155px;border:1px solid #3a5140;border-radius:7px;background:radial-gradient(ellipse at 50% 0%,#354c3a,#1b2c22 75%);position:relative;overflow:hidden;box-shadow:inset 0 0 30px #101c14}
.hero-mini-lamp{position:absolute;top:13px;left:23%;right:23%;height:5px;border-radius:4px;background:#cbe87e;box-shadow:0 6px 28px #c9ec8b4d}
.hero-mini-grid{position:absolute;inset:30px 40px 31px;display:grid;grid-template-columns:repeat(9,1fr);gap:5px;align-items:end}
.mini-pot{height:24px;border:1px solid #60704f;background:#33452e;border-radius:2px;position:relative;display:flex;align-items:flex-end;justify-content:center;padding-bottom:3px}
.mini-plant{width:12px;height:var(--h,24px);position:relative;border-left:2px solid #7ea95d}
.mini-plant:before,.mini-plant:after{content:'';position:absolute;width:9px;height:5px;border-radius:100% 5%;background:#6e9c55;left:1px;top:5px;transform:rotate(-23deg)}
.mini-plant:after{left:-6px;top:11px;transform:rotate(23deg) scaleX(-1);background:#82aa62}
.mini-pot.attention .mini-plant{filter:sepia(.5) saturate(.7)}
.mini-pot.dead{opacity:.35}
.hero-mini-caption{position:absolute;left:11px;right:11px;bottom:8px;display:flex;justify-content:space-between;font:6.5px var(--mono);letter-spacing:.07em;color:#778d79}
.hero-mini-caption span:last-child{display:flex;align-items:center;gap:4px;color:#8fa986}
.hero-mini-caption i{width:4px;height:4px;border-radius:50%;background:#7da45e}
.hero-grow-foot{display:flex;align-items:center;gap:28px;padding:13px 0 15px}
.hero-metric{min-width:58px}
.hero-metric span{display:block;font:6.5px var(--mono);letter-spacing:.08em;color:#7f9481;margin-bottom:3px}
.hero-metric b{font:600 14px var(--display);color:#eef5e4}
.hero-metric .bar{display:block;height:2px;background:#3b5040;margin-top:5px;border-radius:2px;overflow:hidden;width:70px}
.hero-metric .bar i{display:block;height:100%;background:#b4d374;border-radius:2px}
.round-arrow{margin-left:auto;width:31px;height:31px;border-radius:50%;border:1px solid #4a6150;background:transparent;color:#d8e9b9;font-size:15px}
.round-arrow:hover{background:#d9ed9c;color:#24412e;border-color:#d9ed9c}
.oracle-card{background:#f9faf4;border:1px solid #e2e8d9;border-radius:10px;padding:19px 20px;display:flex;flex-direction:column}
.oracle-card-head{display:flex;align-items:center;gap:9px}
.oracle-orb{width:32px;height:32px;display:grid;place-items:center;border-radius:50%;background:#eaf1d9;color:#6b8d4b;font-size:16px;flex-shrink:0}
.oracle-card-head>span:nth-child(2){flex:1}
.oracle-card-head b{display:block;font:650 13px var(--display);letter-spacing:-.02em;margin-top:2px}
.oracle-card>p{font-size:9.5px;line-height:1.55;color:#8a9685;margin:13px 0 14px}
.oracle-suggestion{background:#fff;border:1px solid #e7ecdf;border-radius:6px;padding:10px;display:flex;align-items:center;gap:6px;font:9.5px/1.45 var(--sans);color:#6e7d6d}
.oracle-suggestion span{flex:1}
.oracle-suggestion button{border:0;background:#eff5e2;color:#63834d;width:21px;height:21px;border-radius:4px;font-size:12px;flex-shrink:0}
.oracle-suggestion button:hover{background:#dceac7}
.oracle-link{margin-top:auto;border:0;background:none;padding:14px 0 0;text-align:left;color:#5e7e54;font:600 9px var(--sans)}
.oracle-link span{float:right;font-size:12px}
.panel-columns{display:grid;grid-template-columns:1.55fr .85fr;gap:16px;margin-bottom:16px}
.panel-columns-wide{grid-template-columns:1.4fr .9fr}
.timeline-card{padding-bottom:15px}
.season-track{display:grid;grid-template-columns:repeat(5,1fr);padding:4px 19px 0;gap:0}
.season-node{position:relative;padding-right:10px}
.season-node:before{content:'';position:absolute;top:8px;left:16px;right:-2px;height:1px;background:#e2e7dc}
.season-node:last-child:before{display:none}
.season-dot{width:16px;height:16px;border:1px solid #cdd8c4;background:#f7f9f3;border-radius:50%;position:relative;z-index:1;display:grid;place-items:center}
.season-node.done .season-dot{background:#769a5b;border-color:#769a5b}
.season-node.done .season-dot:after{content:'✓';color:#fff;font-size:7px}
.season-node.current .season-dot{border:3px solid #b9d57b;background:#3b5d3e;box-shadow:0 0 0 3px #edf4dd}
.season-node .sn-name{display:block;font:600 9px var(--display);margin-top:7px;color:#5d705f}
.season-node .sn-days{display:block;font:7px var(--mono);color:#a0aaa1;margin-top:2px}
.season-node.current .sn-name{color:#31583b}
.focus-card{display:flex;flex-direction:column}
.day-stamp{font:8px var(--mono);color:#8d9c88;background:#f3f6ed;padding:4px 6px;border-radius:3px}
.focus-list{padding:0 19px 5px;flex:1}
.focus-item{display:flex;gap:7px;align-items:flex-start;padding:6px 0;border-top:1px solid #f2f4ef;font-size:9.5px;line-height:1.45;color:#7d8a7e}
.focus-item:first-child{border-top:0}
.focus-item span{color:#8dab67;font-size:8px;line-height:1.7}
.focus-card .btn{margin:10px 19px 16px;width:calc(100% - 38px)}
.recent-list{padding:0 19px 9px}
.recent-item{display:flex;align-items:center;gap:9px;padding:8px 0;border-top:1px solid #f2f4ef;cursor:pointer}
.recent-item:hover .recent-title{color:#2e583e;text-decoration:underline;text-underline-offset:2px}
.recent-item:first-child{border-top:0}
.recent-icon{width:25px;height:28px;border:1px solid #e3e8dd;border-radius:3px;background:#f8faf4;color:#8a9d76;display:grid;place-items:center;font:7px var(--mono);flex-shrink:0;position:relative}
.recent-icon:after{content:'';position:absolute;top:-1px;right:-1px;border:3px solid #fff;border-left-color:#dce3d4;border-bottom-color:#dce3d4}
.recent-info{min-width:0;flex:1}
.recent-title{font:600 9.5px var(--display);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#58695b}
.recent-meta{display:block;font:7px var(--mono);color:#a2aba2;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.recent-tag{font:7px var(--mono);color:#94a18d;flex-shrink:0}
.insight-card{background:#f7f9ef;border-color:#e4ead8}
.insight-count{font:700 22px var(--display);color:#9db16a;letter-spacing:-.05em}
.insight-copy{font-size:9.5px;line-height:1.55;color:#819078;margin:0 19px 12px}
.insight-copy b{color:#4e654b}
.insight-pair{display:flex;align-items:center;gap:7px;margin:0 19px 13px;background:#fff;border:1px solid #e8ecdf;border-radius:5px;padding:8px 9px}
.pair-dot{width:5px;height:5px;border-radius:50%;background:#9cb375;flex-shrink:0}
.insight-pair span{font:8px var(--mono);color:#84917e}
.insight-pair b{font:600 8.5px var(--sans);color:#526751;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.insight-card .text-link{margin:0 19px 14px}

/* ===== SIMULADOR ===== */
.sim-head{margin-bottom:19px}
.sim-statusbar{display:flex;align-items:center;background:#fff;border:1px solid var(--line);border-radius:9px;margin-bottom:15px;padding:10px 17px;gap:0;overflow:hidden}
.sim-day{display:flex;flex-direction:column;padding-right:20px;border-right:1px solid var(--line-soft);margin-right:18px}
.sim-day>span{font:6.5px var(--mono);letter-spacing:.1em;color:#9da79e}
.sim-day b{font:700 24px var(--display);letter-spacing:-.055em;line-height:1.1}
.sim-day b small{font:500 8px var(--mono);color:#a5ada6;letter-spacing:0;margin-left:2px}
.sim-status-item{display:flex;flex-direction:column;gap:3px;padding:0 19px;border-right:1px solid var(--line-soft);min-width:0}
.sim-status-item:last-child{border-right:0}
.sim-status-item.wide{margin-left:auto;text-align:right;padding-right:2px}
.sim-status-item .phase-pill{align-self:flex-start}
.sim-status-item small{font:7px var(--mono);color:#a0aaa1}
.sim-status-item b{font:600 11px var(--display);white-space:nowrap}
.sim-status-item .section-kicker{margin:0}
.sim-grid{display:grid;grid-template-columns:minmax(0,1.63fr) minmax(280px,.82fr);gap:15px;align-items:start}
.sim-main,.sim-side{display:grid;gap:14px}
.panel{background:var(--paper);border:1px solid var(--line);border-radius:10px;overflow:hidden}
.panel-heading{display:flex;align-items:center;justify-content:space-between;padding:16px 18px 12px;gap:10px}
.panel-heading h2{font:650 15px var(--display);letter-spacing:-.025em;margin:3px 0 0}
.panel-heading .muted{font:500 10px var(--mono);color:#a0aaa2;letter-spacing:0}
.view-legend{display:flex;gap:11px;color:#929b94;font-size:8.5px;flex-wrap:wrap;justify-content:flex-end}
.view-legend span{display:flex;align-items:center;gap:4px;white-space:nowrap}
.legend-dot{width:5px;height:5px;border-radius:50%;background:#85b36c}
.legend-dot.attention{background:#e8b368}
.legend-dot.dead{background:#a7aaa1}
.greenhouse-scene{margin:0 17px;border-radius:7px;background:#18251e;position:relative;overflow:hidden;height:304px;color:#a8b7aa}
.scene-topline{position:absolute;z-index:2;left:14px;right:14px;top:11px;display:flex;justify-content:space-between;color:#91a398;font:7px var(--mono);letter-spacing:.08em}
.scene-topline span:first-child{color:#829889}
.room{position:absolute;inset:28px 45px 27px;background:linear-gradient(145deg,#293b30,#1f3027 67%,#1d2c24);border:1px solid #3a4b3e;border-radius:3px;box-shadow:inset 0 0 0 8px rgba(13,25,18,.24),0 12px 20px #111b15;transform:perspective(750px) rotateX(1deg)}
.room:before{content:'';position:absolute;inset:10px;background:repeating-linear-gradient(0deg,transparent 0 33px,rgba(168,196,150,.065) 34px 35px),repeating-linear-gradient(90deg,transparent 0 36px,rgba(168,196,150,.055) 37px 38px);pointer-events:none}
.room-wall{position:absolute;top:0;bottom:0;width:8px;background:linear-gradient(90deg,#28392e,#435746);opacity:.8}
.left-wall{left:0}.right-wall{right:0}
.light-bar{position:absolute;top:16px;left:18%;right:18%;height:9px;border-radius:8px;background:#c8e78b;box-shadow:0 5px 24px #d1f19465,0 0 12px #c9ef9c;display:flex;align-items:center;justify-content:center}
.light-bar span{position:absolute;top:4px;width:92%;height:1px;background:#f3ffd1}
.light-bar i{position:absolute;top:-11px;font:6px var(--mono);color:#c3d1bb;letter-spacing:.08em;font-style:normal}
.grow-bed{position:absolute;left:8%;right:8%;top:52px;bottom:31px;border:1px solid #59604a;border-radius:3px;background:linear-gradient(145deg,#4c4736,#3d3d30);box-shadow:inset 0 0 15px #161f19;display:grid;place-items:center;padding:10px}
.bed-grid{width:100%;height:100%;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:6px;z-index:1}
.plant-slot{min-width:0;position:relative;display:grid;place-items:center;cursor:pointer;border:1px solid rgba(188,203,153,.13);background:rgba(38,51,37,.34);border-radius:4px;transition:.18s;padding:0}
.plant-slot:hover,.plant-slot.selected{border-color:#d4ed93;background:#82955725;box-shadow:0 0 0 1px #d4ed9330}
.plant-slot .pot{position:absolute;bottom:4px;width:27px;height:9px;background:linear-gradient(#9b6946,#704831);clip-path:polygon(5% 0,95% 0,84% 100%,16% 100%);z-index:2}
.plant-slot .plant{position:absolute;bottom:10px;width:42px;height:43px;display:grid;place-items:end center;filter:drop-shadow(0 3px 4px #0f1911aa)}
.plant-stem{position:absolute;bottom:0;width:3px;height:calc(var(--grow)*.43px);max-height:33px;background:#81a45e;border-radius:3px}
.leaf{position:absolute;width:17px;height:8px;border-radius:100% 5% 100% 5%;background:#6f9b57;transform-origin:90% 90%}
.leaf.l1{bottom:9px;left:3px;transform:rotate(28deg)}
.leaf.l2{bottom:13px;right:2px;transform:scaleX(-1) rotate(29deg)}
.leaf.l3{bottom:19px;left:6px;transform:rotate(20deg) scale(.8)}
.leaf.l4{bottom:21px;right:4px;transform:scaleX(-1) rotate(24deg) scale(.82)}
.leaf.l5{bottom:26px;left:14px;width:15px;height:8px;transform:rotate(-30deg) scale(.75)}
.plant-slot.bloom .leaf{background:#89a95e}
.plant-slot.bloom .plant:after{content:'';position:absolute;bottom:22px;width:11px;height:12px;background:radial-gradient(ellipse,#d8d69c 0 20%,#a7ba6b 22% 55%,transparent 60%);filter:drop-shadow(0 0 3px #d3d5906b)}
.plant-slot .plant-id{position:absolute;top:3px;left:4px;color:#bdcbb7;font:7px var(--mono);opacity:.7}
.plant-slot .plant-condition{position:absolute;top:3px;right:4px;width:5px;height:5px;background:#92bf6d;border-radius:50%}
.plant-slot.attention .plant-condition{background:#e9b56b}
.plant-slot.dead .plant-condition{background:#c97062}
.plant-slot.dead .leaf,.plant-slot.dead .plant-stem{background:#81674b}
.room-front{position:absolute;bottom:7px;left:0;right:0;display:flex;align-items:center;justify-content:space-between;padding:0 9px;font:6px var(--mono);color:#a0b09f;letter-spacing:.07em}
.vent-lines{display:flex;gap:3px}
.vent-lines i{display:block;width:10px;height:2px;background:#819284;border-radius:1px}
.measure-left{position:absolute;left:-31px;top:47%;font:7px var(--mono);color:#99a998;writing-mode:vertical-rl;transform:rotate(180deg);display:flex;align-items:center;gap:5px}
.measure-left i{height:44px;width:1px;background:#738474}
.scene-glow{position:absolute;width:150px;height:100px;left:calc(50% - 75px);top:36px;background:#b9da7a0a;filter:blur(20px);pointer-events:none}
.scene-footer{position:absolute;left:14px;right:14px;bottom:0;height:27px;display:flex;align-items:center;justify-content:space-between;padding:0 2px;color:#96a098;font:6.5px var(--mono);letter-spacing:.05em}
.mini-icon{font-style:normal;color:#71985f;font-size:11px;margin-right:3px}
.scene-footer b{color:#d4e4c4;font-weight:500}
.plant-detail{height:48px;border-top:1px solid #f0f1ed;display:flex;align-items:center;padding:0 18px;gap:18px}
.detail-title{font:600 10px var(--display);white-space:nowrap}
.detail-title small{display:block;color:#9aa39b;font:8px var(--mono);margin-top:3px}
.detail-stat{display:flex;align-items:center;gap:5px;color:#9ba39c;font:7.5px var(--mono);white-space:nowrap}
.detail-stat b{color:#425348;font:600 9.5px var(--sans)}
.detail-bar{width:44px;height:3px;background:#edf0e9;border-radius:3px;overflow:hidden;display:inline-block}
.detail-bar i{display:block;height:100%;background:#80a75e;border-radius:4px}
.detail-note{margin-left:auto;font-size:9px;color:#7a8a7f;white-space:nowrap}
.controls-heading{padding-bottom:10px}
.action-hint{font:7px var(--mono);color:#a0a9a1;text-align:right}
.action-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;padding:0 17px 14px}
.action-card{height:59px;text-align:left;border:1px solid #e9ece6;background:#fff;border-radius:7px;padding:8px 8px;display:grid;grid-template-columns:25px 1fr;grid-template-rows:1fr auto;align-items:center;column-gap:6px;transition:.18s;color:var(--ink)}
.action-card:hover:not(:disabled){border-color:#c3d2b7;background:#f8faf5;transform:translateY(-1px)}
.action-card:disabled{opacity:.42;cursor:not-allowed}
.action-icon{grid-row:1/3;align-self:center;display:grid;place-items:center;width:25px;height:25px;background:#eff5e9;color:#628351;border-radius:6px;font-size:14px}
.water-icon{background:#eaf4f5;color:#52939a}
.feed-icon{background:#f0f3e7}
.inspect-icon{background:#f5f0e5;color:#997f4f}
.vent-icon{background:#eef1f1;color:#6b8790}
.harvest-icon{background:#f7eee6;color:#a3794e}
.action-card b{display:block;font:600 9.5px var(--display)}
.action-card small{display:block;color:#a0a8a0;font-size:7px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.action-cost{grid-column:2;font:6.5px var(--mono);color:#a5aea4;letter-spacing:.03em;white-space:nowrap}
.advance-row{border-top:1px solid #eef0eb;display:flex;justify-content:space-between;align-items:center;padding:11px 17px;gap:14px}
.tip{display:flex;align-items:start;gap:8px;min-width:0}
.tip>span:first-child{color:#8a9e60;font-size:13px}
.tip b,.tip small{display:block}
.tip b{font:600 8.5px var(--display);color:#526257}
.tip small{font-size:8.5px;color:#9aa29a;margin-top:2px;line-height:1.45}
.advance-button{border:0;border-radius:6px;background:#294b35;color:#f4f7ed;height:34px;padding:0 11px 0 13px;display:flex;align-items:center;gap:15px;font:600 9.5px var(--sans);box-shadow:0 3px 7px #294b3522;transition:.2s;white-space:nowrap;flex-shrink:0}
.advance-button:hover{background:#376648;transform:translateY(-1px)}
.advance-button b{font-size:15px;color:#d5ec9a}
.compact{padding:14px 15px 10px}
.compact .section-kicker{font-size:6.5px}
.compact h2{font-size:13.5px}
.climate-icon{display:grid;place-items:center;width:27px;height:27px;color:#a3b46b;background:#f1f5e8;border-radius:50%;font-size:16px}
.climate-readings{padding:0 15px}
.reading{height:50px;display:flex;align-items:center;border-top:1px solid #f0f2ed;gap:8px}
.reading-icon{width:26px;height:26px;border-radius:7px;display:grid;place-items:center;background:#f5f2e9;color:#9a8b5e;font-size:14px;flex-shrink:0}
.reading-icon.humidity{background:#edf5f5;color:#5f9a9e}
.reading-icon.light{background:#f4f5e9;color:#9fa45d}
.reading>div{flex:1;min-width:0}
.reading .label{font-size:6.5px}
.reading>div>b{display:block;font:600 14px var(--display);margin-top:2px}
.reading>div>b small{font:500 8px var(--mono);color:#8a978b;margin-left:2px}
.reading-state{font:6px var(--mono);letter-spacing:.03em;padding:3px 4px;border-radius:3px;white-space:nowrap}
.reading-state.good{background:#f0f5e9;color:#77935b}
.reading-state.warn{background:#fbf2df;color:#ad8d4a}
.reading-state.bad{background:#f9e9e3;color:#b56e5b}
.climate-note{display:flex;gap:7px;margin:2px 15px 13px;padding:8px 9px;background:#f7f8f4;border-radius:5px;color:#8e9a90;font-size:8.5px;line-height:1.45}
.climate-note>span:first-child{color:#78995a}
.plus-button{border:1px solid #e4e9df;background:#f7f9f4;width:25px;height:25px;border-radius:6px;color:#648251;font-size:18px;line-height:1;cursor:pointer}
.plus-button:hover{background:#edf3e6}
.resource-list{padding:0 15px}
.resource{display:flex;align-items:center;gap:8px;margin:7px 0 11px}
.resource-symbol{width:27px;height:27px;border-radius:7px;display:grid;place-items:center;background:#edf5f5;color:#57949a;font-size:14px;flex-shrink:0}
.nutrient-symbol{background:#f1f4e7;color:#869a55}
.energy-symbol{background:#f5f1e7;color:#af9955}
.resource-info{flex:1;min-width:0}
.resource-info>b{display:block;font:600 8.5px var(--display);margin-bottom:4px}
.resource-meter{height:3px;background:#edf0eb;border-radius:3px;overflow:hidden;width:100%}
.resource-meter i{height:100%;background:#70a2a3;display:block;border-radius:4px;transition:width .3s}
.nutrient-meter i{background:#9eae61}
.energy-meter i{background:#c0a556}
.resource>strong{font:600 9px var(--mono);white-space:nowrap}
.resource>strong small{color:#a3aaa3;font-size:7px;font-weight:400}
.resource-foot{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #eff1ec;padding:9px 15px;color:#a0a89f;font:6.5px var(--mono);letter-spacing:.03em}
.resource-foot b{font:600 8.5px var(--sans);color:#58685d}
.resource-foot b small{color:#a5afa4}
.log-list{padding:0 15px 8px}
.log-item{display:flex;gap:7px;padding:7px 0;border-top:1px solid #f1f2ee}
.log-time{font:7px var(--mono);color:#a1aaa1;white-space:nowrap;padding-top:1px}
.log-text{font-size:8.5px;color:#69766c;line-height:1.4}
.log-text b{font-weight:600;color:#445449}
.log-mark{width:5px;height:5px;border-radius:50%;background:#8aa66b;margin-top:3px;flex-shrink:0}
.log-mark.warning{background:#ddb570}
.log-mark.success{background:#76a29b}
.log-count{font:8px var(--mono);color:#a7afa8}
.goal-card{display:flex;gap:10px;padding:13px;background:#eaf0e1;border-radius:9px;color:#4d6249}
.goal-spark{font-size:17px;color:#8fa666}
.goal-card .section-kicker{font-size:6.5px;color:#829272}
.goal-card b{display:block;margin-top:4px;font:650 11px var(--display)}
.goal-card p{font-size:8px;color:#84907f;line-height:1.4;margin:3px 0 7px}
.goal-progress{height:3px;background:#d9e2cd;border-radius:4px;overflow:hidden}
.goal-progress i{height:100%;display:block;background:#7d9e5e;border-radius:4px;transition:width .3s}
.goal-card small{display:block;text-align:right;font:7px var(--mono);color:#87947d;margin-top:4px}

/* ===== LIBRARY ===== */
.library-stats{display:grid;grid-template-columns:repeat(4,1fr) 1.5fr;background:#fff;border:1px solid var(--line);border-radius:9px;padding:14px 0;margin-bottom:15px}
.library-stats>div{padding:0 17px;border-right:1px solid var(--line-soft)}
.library-stats>div:last-child{border-right:0}
.library-stats span{display:block;font:6.5px var(--mono);letter-spacing:.08em;color:#9ea89f;margin-bottom:4px}
.library-stats b{font:700 20px var(--display);letter-spacing:-.04em}
.library-stats .lib-storage{display:flex;flex-direction:column;justify-content:center}
.library-stats .lib-storage b{font-size:12px}
.library-stats .lib-storage small{font:7px var(--mono);color:#9ca79d;margin-top:2px}
.library-toolbar{display:flex;gap:8px;margin-bottom:12px;align-items:center}
.search-field{height:38px;flex:1;background:#fff;border:1px solid var(--line);border-radius:7px;display:flex;align-items:center;gap:8px;padding:0 11px;min-width:0}
.search-field span{color:#8fa08f;font-size:15px}
.search-field input{flex:1;border:0;outline:0;background:none;font-size:10.5px;min-width:0}
.search-field input::placeholder{color:#aab2aa}
.search-field kbd{font:7px var(--mono);color:#a8b0a8;background:#f4f6f1;border:1px solid #e8ece3;border-radius:3px;padding:3px 5px}
.select{height:38px;border:1px solid var(--line);background:#fff;border-radius:7px;padding:0 27px 0 10px;font-size:9.5px;color:#6d7d6f;appearance:none;background-image:linear-gradient(45deg,transparent 50%,#97a398 50%),linear-gradient(135deg,#97a398 50%,transparent 50%);background-position:calc(100% - 13px) 16px,calc(100% - 9px) 16px;background-size:4px 4px,4px 4px;background-repeat:no-repeat;cursor:pointer;min-width:155px}
.toggle-btn{height:38px;border:1px solid var(--line);background:#fff;border-radius:7px;padding:0 11px;font-size:9.5px;color:#728075;display:flex;align-items:center;gap:6px;white-space:nowrap}
.toggle-btn.active{background:#f0f5e7;border-color:#cbd9bd;color:#516b4f}
.toggle-dot{width:7px;height:7px;border:1px solid #aeb9ac;border-radius:2px}
.toggle-btn.active .toggle-dot{background:#809f5e;border-color:#809f5e}
.dup-banner{display:flex;align-items:center;gap:12px;background:#f7f9ef;border:1px solid #e3e9d6;border-radius:8px;padding:11px 14px;margin-bottom:14px}
.dup-banner-icon{width:30px;height:30px;border-radius:7px;background:#ecf2dd;color:#78935a;display:grid;place-items:center;font-size:14px;flex-shrink:0}
.dup-banner>div{flex:1;min-width:0}
.dup-banner b{display:block;font:650 10.5px var(--display);color:#52664c;margin-bottom:2px}
.dup-banner p{font-size:8.5px;color:#8c9985;line-height:1.45;margin:0}
.dup-banner button{border:0;background:none;color:#668353;font:600 9px var(--sans);white-space:nowrap;padding:0}
.dup-banner button:hover{text-decoration:underline}
.library-layout{display:grid;grid-template-columns:minmax(0,1fr) 335px;gap:14px;align-items:start}
.library-list-card{background:#fff;border:1px solid var(--line);border-radius:9px;overflow:hidden}
.list-head{display:flex;justify-content:space-between;padding:10px 15px;border-bottom:1px solid var(--line-soft);font:7px var(--mono);letter-spacing:.05em;color:#98a299}
.list-head-legend{display:flex;align-items:center;gap:5px}
.list-head-legend i{width:4px;height:4px;border-radius:50%;background:#8aa46c}
.lib-list{max-height:none}
.lib-row{display:flex;gap:10px;padding:11px 14px;border-bottom:1px solid #f3f5f0;cursor:pointer;transition:.15s;align-items:flex-start}
.lib-row:last-child{border-bottom:0}
.lib-row:hover{background:#fafbf7}
.lib-row.selected{background:#f4f8ed;box-shadow:inset 2px 0 #8aa962}
.lib-pdf{width:27px;height:32px;border:1px solid #e2e8da;border-radius:3px;background:#f8faf4;color:#8a9d76;display:grid;place-items:center;font:6px var(--mono);flex-shrink:0;position:relative;margin-top:1px}
.lib-pdf:after{content:'';position:absolute;top:-1px;right:-1px;border:3px solid #fff;border-left-color:#dce3d4;border-bottom-color:#dce3d4}
.lib-row-main{flex:1;min-width:0}
.lib-title-line{display:flex;align-items:center;gap:6px}
.lib-title{font:600 10.5px var(--display);letter-spacing:-.01em;color:#425348;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dup-mini{font:5.5px var(--mono);color:#829567;background:#eef4e2;border-radius:2px;padding:2px 3px;white-space:nowrap;flex-shrink:0}
.lib-meta{font:7px var(--mono);color:#9ba59c;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lib-meta b{font-weight:500;color:#748673}
.lib-path{font:6.5px var(--mono);color:#aab2a9;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lib-row-side{display:flex;flex-direction:column;align-items:flex-end;gap:5px;flex-shrink:0;padding-top:1px}
.state-badge{font:6px var(--mono);letter-spacing:.03em;padding:3px 5px;border-radius:3px;white-space:nowrap}
.state-markdown{background:#eef4e5;color:#62834f}
.state-procesado{background:#f4f1e8;color:#988757}
.state-pendiente{background:#f5f2ed;color:#a59d8c}
.lib-pages{font:6.5px var(--mono);color:#aab2a9}
.lib-empty{padding:40px 20px;text-align:center}
.lib-empty b{font:650 14px var(--display);display:block;margin-bottom:5px}
.lib-empty p{font-size:10px;color:#98a299;margin:0 0 10px}
.resource-detail{background:#fff;border:1px solid var(--line);border-radius:9px;padding:18px;position:sticky;top:84px;min-height:405px}
.rd-top{display:flex;justify-content:space-between;align-items:start}
.rd-icon{width:40px;height:46px;background:#f7faf2;border:1px solid #e3e9da;border-radius:4px;display:grid;place-items:center;font:7px var(--mono);color:#8ba176;position:relative}
.rd-icon:after{content:'';position:absolute;top:-1px;right:-1px;border:4px solid #fff;border-left-color:#dce3d4;border-bottom-color:#dce3d4}
.rd-badge{font:6.5px var(--mono);color:#708766;background:#eff5e5;border-radius:3px;padding:4px 6px}
.resource-detail h2{font:650 18px/1.25 var(--display);letter-spacing:-.035em;margin:12px 0 5px;color:#2b4033}
.rd-origin{font:8px var(--mono);color:#93a08f;line-height:1.6}
.rd-origin b{color:#6f825e;font-weight:500}
.rd-summary{font-size:9.5px;line-height:1.6;color:#7f8c80;margin:13px 0;padding-bottom:13px;border-bottom:1px solid #f0f2ed}
.rd-facts{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:12px}
.rd-fact span{display:block;font:6px var(--mono);letter-spacing:.06em;color:#a3aca3;margin-bottom:2px}
.rd-fact b{font:600 9px var(--sans);color:#5a6c5c;word-break:break-word}
.rd-path{background:#f8faf4;border:1px solid #edf1e8;border-radius:5px;padding:8px;font:7px/1.5 var(--mono);color:#8b9a83;word-break:break-all;margin-bottom:12px}
.rd-path b{display:block;color:#788c71;font-weight:500;margin-bottom:3px;font-size:6px;letter-spacing:.06em}
.rd-tags{display:flex;flex-wrap:wrap;gap:4px;margin-bottom:13px}
.rd-tags span{font:6.5px var(--mono);color:#7d9075;background:#f2f5ed;padding:3px 5px;border-radius:3px}
.rd-actions{display:flex;gap:6px}
.rd-actions .btn{height:31px;font-size:8.5px;flex:1;padding:0 7px;gap:6px}
.rd-dup{background:#f7f9ef;border:1px solid #e7ecdb;border-radius:5px;padding:8px 9px;margin-bottom:11px}
.rd-dup b{font:600 8px var(--sans);color:#667b56;display:block;margin-bottom:3px}
.rd-dup p{font:7px/1.5 var(--mono);color:#94a08b;margin:0}
.rd-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:340px;text-align:center;color:#9aa69a}
.rd-empty span{font-size:26px;color:#c0cdb8;margin-bottom:10px}
.rd-empty b{font:650 13px var(--display);color:#6f806f;margin-bottom:4px}
.rd-empty p{font-size:9px;line-height:1.6;max-width:200px;margin:0}

/* ===== ORACLE ===== */
.oracle-head{margin-bottom:20px}
.oracle-badge-large{display:flex;align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:8px;padding:10px 13px;flex-shrink:0}
.oracle-badge-large .oracle-orb{width:31px;height:31px}
.oracle-badge-large b{display:block;font:600 9.5px var(--display);margin-top:2px}
.oracle-badge-large small{display:block;font:7px var(--mono);color:#a1aba1;margin-top:2px}
.oracle-layout{display:grid;grid-template-columns:minmax(0,1.55fr) 325px;gap:15px;align-items:start}
.chat-card{background:#fff;border:1px solid var(--line);border-radius:10px;overflow:hidden;display:flex;flex-direction:column;height:624px}
.chat-head{display:flex;align-items:center;justify-content:space-between;padding:13px 16px;border-bottom:1px solid var(--line-soft)}
.chat-title{display:flex;align-items:center;gap:9px}
.oracle-orb.small{width:29px;height:29px;font-size:14px}
.chat-title b{display:block;font:650 11px var(--display)}
.chat-title small{display:flex;align-items:center;gap:5px;font:7px var(--mono);color:#a0aaa0;margin-top:2px}
.chat-title .live-dot{width:4px;height:4px;box-shadow:none}
.chat-log{padding:16px;overflow-y:auto;flex:1;display:flex;flex-direction:column;gap:12px;scroll-behavior:smooth}
.msg{display:flex;gap:8px;max-width:88%;animation:msgIn .22s ease}
@keyframes msgIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
.msg.user{align-self:flex-end;flex-direction:row-reverse}
.msg-avatar{width:23px;height:23px;border-radius:50%;background:#eef4e2;color:#728f58;display:grid;place-items:center;font-size:10px;flex-shrink:0}
.msg.user .msg-avatar{background:#2a4734;color:#ddedc1;font:600 7px var(--mono)}
.msg-body{background:#f7f9f3;border:1px solid #edf1e8;border-radius:2px 9px 9px 9px;padding:10px 12px;font-size:10px;line-height:1.62;color:#66756a;min-width:0}
.msg.user .msg-body{background:#2c4a36;border-color:#2c4a36;color:#edf4e4;border-radius:9px 2px 9px 9px}
.msg-body p{margin:0 0 6px}
.msg-body p:last-child{margin-bottom:0}
.msg-body b{font-weight:600;color:#3e5843}
.msg.user .msg-body b{color:#fff}
.msg-body ul{margin:4px 0 6px;padding-left:14px}
.msg-body li{margin-bottom:3px}
.msg-body .cite{display:inline-block;font:6.5px var(--mono);background:#eaf1dd;color:#728d58;border-radius:2px;padding:2px 4px;margin:0 2px 2px 0}
.msg-body .legal-callout{background:#fbf6e9;border-left:2px solid #d3b978;padding:6px 8px;color:#8d7d56;font-size:8.5px;border-radius:0 3px 3px 0;margin-top:7px}
.typing{display:flex;gap:3px;padding:3px 1px}
.typing i{width:4px;height:4px;background:#9bae8f;border-radius:50%;animation:blink 1s infinite}
.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}
@keyframes blink{0%,100%{opacity:.3;transform:translateY(0)}50%{opacity:1;transform:translateY(-2px)}}
.chat-prompts{display:flex;gap:5px;padding:0 14px 9px;flex-wrap:wrap}
.chat-prompts button{border:1px solid #e7ebdf;background:#fafbf6;border-radius:10px;padding:5px 8px;font:8px var(--sans);color:#7b8a79;transition:.15s}
.chat-prompts button:hover{background:#eff5e5;border-color:#cfdbc3;color:#516b4d}
.chat-input{display:flex;margin:0 14px 10px;border:1px solid #dfe6d8;border-radius:7px;overflow:hidden;background:#fff}
.chat-input input{flex:1;border:0;outline:0;height:39px;padding:0 12px;font-size:10px;background:transparent;min-width:0}
.chat-input button{width:42px;border:0;background:#2b4c36;color:#d9ecb7;font-size:15px}
.chat-input button:hover{background:#386648}
.chat-disclaimer{text-align:center;font:6.5px/1.5 var(--mono);color:#a6afa6;padding:0 18px 11px}
.sources-card{background:#fff;border:1px solid var(--line);border-radius:10px;overflow:hidden;position:sticky;top:84px}
.sources-head{display:flex;justify-content:space-between;align-items:center;padding:14px 15px 10px;border-bottom:1px solid var(--line-soft)}
.sources-head .section-kicker{margin:0}
.sources-head>span:last-child{font:8px var(--mono);color:#a1aba1}
.sources-list{padding:8px 12px;min-height:190px}
.sources-empty{padding:35px 12px;text-align:center;color:#a4aea4}
.sources-empty span{font-size:24px;color:#c5d1bc;display:block;margin-bottom:8px}
.sources-empty p{font-size:8.5px;line-height:1.6;margin:0;max-width:190px;margin:auto}
.source-item{padding:9px 5px;border-bottom:1px solid #f1f3ee;cursor:pointer}
.source-item:last-child{border-bottom:0}
.source-item:hover .source-title{color:#31583b}
.source-title{font:600 8.5px/1.35 var(--display);color:#566a58;margin-bottom:3px}
.source-meta{font:6.5px var(--mono);color:#a0aaa0;line-height:1.5}
.source-score{float:right;font:6px var(--mono);color:#8fa383;background:#f1f5e9;padding:2px 3px;border-radius:2px;margin-left:4px}
.oracle-how{border-top:1px solid var(--line-soft);padding:13px 16px;background:#fafbf6}
.oracle-how b{font:600 9px var(--display);color:#5e715f}
.oracle-how ol{margin:7px 0 0;padding-left:14px}
.oracle-how li{font-size:7.5px;line-height:1.65;color:#96a196}

/* ===== BUDGET ===== */
.budget-grid{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:16px;align-items:start}
.budget-controls{padding-bottom:14px}
.scenario-tag{font:6.5px var(--mono);color:#7d9169;background:#eff5e5;padding:4px 6px;border-radius:3px;letter-spacing:.05em;white-space:nowrap}
.control-group{padding:0 19px;margin-bottom:15px}
.control-label{display:flex;justify-content:space-between;margin-bottom:8px}
.control-label span{font:9px var(--sans);color:#66766a}
.control-label b{font:600 10px var(--mono);color:#415a43}
.control-group input[type=range]{width:100%;height:3px;appearance:none;background:#e7ece1;border-radius:3px;outline:none}
.control-group input[type=range]::-webkit-slider-thumb{appearance:none;width:12px;height:12px;border-radius:50%;background:#507a4a;border:2px solid #fff;box-shadow:0 1px 4px #2f4b3233;cursor:pointer}
.control-group input[type=range]::-moz-range-thumb{width:10px;height:10px;border-radius:50%;background:#507a4a;border:2px solid #fff;cursor:pointer}
.range-scale{display:flex;justify-content:space-between;font:6px var(--mono);color:#a4ada3;margin-top:6px}
.control-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:0 19px;margin-bottom:12px}
.field span{display:block;font:6.5px var(--mono);letter-spacing:.04em;color:#8e9a90;margin-bottom:5px}
.field input,.field select{width:100%;height:33px;border:1px solid #e4e9df;border-radius:5px;background:#fafbf7;padding:0 8px;font-size:9.5px;outline:0;color:#536658}
.field input:focus,.field select:focus{border-color:#b9cbaa;background:#fff}
.assumption-note{display:flex;gap:7px;margin:3px 19px 12px;padding:8px 9px;background:#f7f9f3;border-radius:5px}
.assumption-note span{color:#8aa178;font-size:10px}
.assumption-note p{font-size:7.5px;line-height:1.55;color:#96a096;margin:0}
.legal-scale{display:flex;gap:8px;align-items:start;margin:0 19px;padding:9px 10px;background:#eef3e5;border-radius:6px}
.legal-scale-ico{display:grid;place-items:center;width:23px;height:23px;border-radius:50%;background:#e2ebd4;color:#728e57;font-size:11px;flex-shrink:0}
.legal-scale b{display:block;font:600 8.5px var(--display);color:#55704d;margin-bottom:2px}
.legal-scale p{font-size:7.5px;line-height:1.5;color:#8a9980;margin:0}
.budget-results{display:grid;gap:14px}
.budget-total{background:linear-gradient(135deg,#23402e,#1b3225);border-radius:10px;padding:19px 21px;color:#a9b9a9}
.budget-total-top{display:flex;justify-content:space-between;align-items:center}
.budget-total .section-kicker{color:#8fa48e}
.budget-chip{font:6.5px var(--mono);color:#a9c47f;background:#314c38;padding:4px 6px;border-radius:3px}
.budget-big{font:700 45px/1 var(--display);letter-spacing:-.06em;color:#f0f6e7;margin:12px 0 8px}
.budget-big:before{content:'$';font-size:22px;vertical-align:top;line-height:1.5;color:#a8c67a;margin-right:1px}
.budget-sub{display:flex;gap:8px;font-size:8.5px;color:#8da38e}
.budget-sub b{color:#dbe8cc;font-weight:500}
.budget-highlight{display:flex;align-items:center;gap:8px;margin-top:16px;padding-top:12px;border-top:1px solid #36503d;font-size:8.5px}
.budget-highlight b{color:#e8f2d6;font:600 12px var(--display)}
.budget-highlight i{margin-left:auto;font:500 7px var(--mono);font-style:normal;color:#a9c879;background:#2e4b35;padding:4px 5px;border-radius:3px}
.breakdown-card{padding-bottom:12px}
.breakdown-card .mono-note{font:7px var(--mono);color:#a4ada4}
.breakdown-bars{padding:0 19px}
.bd-row{display:grid;grid-template-columns:82px 1fr 62px;align-items:center;gap:8px;margin-bottom:9px}
.bd-name{font-size:8.5px;color:#748377}
.bd-track{height:6px;background:#f0f3ec;border-radius:4px;overflow:hidden}
.bd-track i{display:block;height:100%;border-radius:4px;transition:width .35s}
.bd-val{text-align:right;font:6.5px var(--mono);color:#8c998d}
.compare-card{padding-bottom:13px}
.projection-tag{font:6.5px var(--mono);color:#9c8555;background:#f7f0e2;padding:3px 5px;border-radius:3px}
.compare-copy{font-size:8.5px;line-height:1.55;color:#8f9a90;margin:0 19px 10px}
.scale-table{padding:0 19px}
.scale-row{display:grid;grid-template-columns:1.4fr 1fr .7fr .9fr;align-items:center;gap:5px;padding:6px 0;border-top:1px solid #f1f3ee;font:7px var(--mono);color:#8e9a8e}
.scale-head{font:6px var(--mono);color:#a8b0a7;border-top:0;padding-bottom:3px}
.scale-row b{font:600 8.5px var(--sans);color:#566a58;display:block}
.scale-row small{display:block;font:6px var(--mono);color:#a6afa5;margin-top:2px}
.scale-row span:nth-child(2),.scale-row span:nth-child(3){color:#66776a}
.scale-ok{font:5.5px var(--mono);color:#6f8d57;background:#eff5e5;padding:3px 3px;border-radius:2px;text-align:center}
.scale-warn{font:5.5px var(--mono);color:#a08b55;background:#f8f2e5;padding:3px 3px;border-radius:2px;text-align:center}
.compare-foot{font-size:7.5px;color:#9aa49a;margin:10px 19px 0;padding-top:9px;border-top:1px solid #f0f2ed}
.compare-foot b{color:#72915a}

/* ===== PROCESS ===== */
.process-summary{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr;background:#fff;border:1px solid var(--line);border-radius:9px;padding:14px 0;margin-bottom:16px}
.process-summary>div{padding:0 17px;border-right:1px solid var(--line-soft);min-width:0}
.process-summary>div:last-child{border-right:0}
.process-summary b{display:block;font:600 12px var(--display);margin:3px 0 2px}
.process-summary small{font:7px var(--mono);color:#a1aaa1}
.big-progress{height:4px;background:#edf0e9;border-radius:4px;margin-top:7px;overflow:hidden;max-width:180px}
.big-progress i{display:block;height:100%;background:#86a760;border-radius:4px;transition:width .3s}
.process-layout{display:grid;grid-template-columns:minmax(0,1.65fr) 320px;gap:16px;align-items:start}
.process-timeline{background:#fff;border:1px solid var(--line);border-radius:9px;padding:5px 0}
.phase-block{display:grid;grid-template-columns:62px 1fr;position:relative;padding:13px 19px 13px 0}
.phase-block:before{content:'';position:absolute;left:40px;top:0;bottom:0;width:1px;background:#e8ece3}
.phase-block:last-child:before{bottom:50%}
.phase-marker{position:relative;z-index:1;display:flex;justify-content:center;padding-top:3px}
.phase-marker span{width:27px;height:27px;border-radius:50%;display:grid;place-items:center;background:#f2f6ea;border:1px solid #dae4ce;color:#78965e;font-size:11px}
.phase-block.current .phase-marker span{background:#2f5239;border-color:#2f5239;color:#d9edaf;box-shadow:0 0 0 4px #edf3e2}
.phase-block.done .phase-marker span{background:#8eab68;border-color:#8eab68;color:#fff}
.phase-content{border-bottom:1px solid #f0f2ed;padding-bottom:14px}
.phase-block:last-child .phase-content{border-bottom:0;padding-bottom:0}
.phase-head{display:flex;align-items:start;justify-content:space-between;gap:10px;margin-bottom:3px}
.phase-title{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.phase-title h3{font:650 14px var(--display);letter-spacing:-.02em;margin:0}
.phase-title span{font:6.5px var(--mono);color:#95a193;background:#f4f6f0;padding:3px 5px;border-radius:3px}
.phase-goal{font:7.5px var(--mono);color:#a0aaa0;margin-bottom:9px}
.phase-cost{text-align:right;font:600 9px var(--mono);color:#72886a;white-space:nowrap}
.phase-cost small{display:block;font:6px var(--mono);color:#a6afa5;margin-top:2px}
.phase-tasks{display:grid;gap:2px}
.task{display:flex;align-items:flex-start;gap:7px;font-size:8.5px;line-height:1.45;color:#7f8c80;padding:3px 0;cursor:pointer}
.task input{display:none}
.task .chk{width:11px;height:11px;border:1px solid #ccd7c4;border-radius:2px;flex-shrink:0;margin-top:1px;display:grid;place-items:center;transition:.15s}
.task.done .chk{background:#7d9e5e;border-color:#7d9e5e}
.task.done .chk:after{content:'✓';font-size:6px;color:#fff}
.task.done span:last-child{color:#a8b2a8;text-decoration:line-through}
.phase-focus{margin-top:8px;display:flex;gap:6px;flex-wrap:wrap}
.phase-focus span{font:6.5px var(--mono);color:#8b9a81;background:#f7f9f2;border:1px solid #edf1e7;padding:3px 5px;border-radius:3px}
.process-side{display:grid;gap:14px}
.legality-card{padding-bottom:13px}
.legality-card .card-head{padding-bottom:9px}
.legal-checks{padding:0 18px}
.legal-check-row{display:flex;gap:8px;align-items:flex-start;padding:7px 0;border-top:1px solid #f1f3ee;cursor:pointer}
.legal-check-row:first-child{border-top:0}
.legal-check-row .chk{width:12px;height:12px;border:1px solid #cbd6c3;border-radius:3px;flex-shrink:0;margin-top:1px;display:grid;place-items:center}
.legal-check-row.done .chk{background:#7d9e5e;border-color:#7d9e5e}
.legal-check-row.done .chk:after{content:'✓';font-size:6px;color:#fff}
.legal-check-row b{display:block;font:600 8.5px/1.4 var(--sans);color:#677a67;margin-bottom:2px}
.legal-check-row.done b{color:#a0aca0;text-decoration:line-through}
.legal-check-row small{font-size:7.5px;line-height:1.45;color:#9aa59b}
.legality-note{font:6.5px/1.55 var(--mono);color:#a2aca2;margin:11px 18px 0;padding-top:10px;border-top:1px solid #f0f2ed}
.budget-teaser{padding:16px 18px}
.budget-teaser .section-kicker{margin-bottom:4px}
.budget-teaser h2{font:650 13px var(--display);margin:0 0 9px}
.teaser-amount{font:700 31px var(--display);letter-spacing:-.05em;color:#31573e}
.teaser-amount small{font:500 8px var(--mono);color:#9da89e;margin-left:4px;letter-spacing:0}
.budget-teaser p{font-size:8.5px;line-height:1.55;color:#939f95;margin:5px 0 12px}
.source-teaser{padding:16px 18px;background:#f7f9ef;border-color:#e4ead8}
.source-teaser h2{font:650 12px var(--display);margin:3px 0 6px;color:#52674f}
.source-teaser p{font-size:8.5px;line-height:1.5;color:#8f9b87;margin:0 0 8px}

/* ===== MODALS / TOAST ===== */
.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,20px);padding:10px 16px;border-radius:7px;background:#233b2c;color:#f2f7eb;font-size:10px;opacity:0;pointer-events:none;transition:.25s;box-shadow:0 8px 25px #15251a33;z-index:40;max-width:90vw;text-align:center}
.toast.show{opacity:1;transform:translate(-50%,0)}
.modal-backdrop{position:fixed;inset:0;background:#101a16a8;display:none;align-items:center;justify-content:center;padding:20px;z-index:30;backdrop-filter:blur(3px)}
.modal-backdrop.open{display:flex}
.modal{position:relative;background:#fff;border-radius:11px;padding:26px 28px;width:min(460px,100%);max-height:90vh;overflow:auto;box-shadow:0 24px 80px #111a1640;animation:pop .2s ease-out}
@keyframes pop{from{transform:translateY(8px);opacity:.7}to{transform:none;opacity:1}}
.modal-close{position:absolute;top:12px;right:15px;border:0;background:none;color:#829087;font-size:23px;cursor:pointer;line-height:1}
.modal h2{font:650 20px var(--display);letter-spacing:-.04em;margin:8px 0}
.modal>p{font-size:10px;line-height:1.6;color:#818c82;margin:0 0 16px}
.guide-list>div{display:flex;gap:12px;padding:9px 0;border-top:1px solid #edf0ea}
.guide-list>div>span{font:9px var(--mono);color:#92a66b;padding-top:2px}
.guide-list p{font-size:9px;line-height:1.55;color:#828c83;margin:0}
.guide-list b{color:#435448;font-weight:600}
.modal .btn.full{margin-top:14px;justify-content:space-between}
.shop-items{display:grid;gap:7px}
.shop-items button{border:1px solid #e9ece6;background:#fff;border-radius:7px;padding:10px;display:flex;align-items:center;text-align:left;gap:9px;cursor:pointer}
.shop-items button:hover{background:#f8faf5;border-color:#c9d7bd}
.shop-items button>span:nth-child(2){flex:1}
.shop-items button b,.shop-items button small{display:block}
.shop-items button b{font:600 9.5px var(--display)}
.shop-items button small{font-size:8px;color:#99a299;margin-top:2px}
.shop-items button strong{font:600 9px var(--mono);color:#506550;text-align:right}
.shop-items button strong i{display:block;font:6px var(--mono);font-style:normal;color:#98a393;margin-top:3px}
.wallet{display:flex;justify-content:space-between;border-top:1px solid #eef0eb;margin-top:14px;padding-top:12px;color:#9aa49a;font:7px var(--mono)}
.wallet b{font:600 12px var(--display);color:#43564a}
.quick-modal{width:min(490px,100%)}
.strategy-list{display:grid;gap:7px;margin-bottom:12px}
.strategy-list button{border:1px solid #e9ece6;background:#fff;border-radius:7px;padding:11px;display:flex;align-items:flex-start;text-align:left;gap:9px;cursor:pointer}
.strategy-list button.active{border-color:#b8cd9f;background:#f6faef;box-shadow:inset 0 0 0 1px #dbe8cc}
.strategy-ico{width:23px;height:23px;border-radius:6px;background:#f1f5e8;color:#779157;display:grid;place-items:center;font-size:12px;flex-shrink:0}
.strategy-list span:nth-child(2){flex:1}
.strategy-list b{display:block;font:600 9.5px var(--display)}
.strategy-list small{display:block;font-size:8px;line-height:1.4;color:#9aa39a;margin-top:2px}
.strategy-list i{font:5.5px var(--mono);font-style:normal;color:#80986a;background:#eef4e4;padding:3px 4px;border-radius:2px;white-space:nowrap}
.quick-note{display:flex;gap:6px;background:#f8f9f4;border-radius:5px;padding:8px;font-size:7.5px;line-height:1.5;color:#96a096;margin-bottom:12px}
.quick-note span{color:#829d72}
.result-modal{width:min(480px,100%)}
.result-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:13px 0}
.result-grid>div{background:#f7f9f2;border-radius:6px;padding:10px}
.result-grid span{display:block;font:6px var(--mono);letter-spacing:.05em;color:#a0aba0;margin-bottom:3px}
.result-grid b{font:700 17px var(--display);letter-spacing:-.04em;color:#35563e}
.result-copy{font-size:9px;line-height:1.6;color:#819082}
.result-lessons{display:grid;gap:4px;margin:8px 0 14px}
.result-lessons div{font-size:8.5px;line-height:1.5;color:#7e8e7d;background:#fafbf6;padding:7px 8px;border-left:2px solid #b9cf9b;border-radius:0 3px 3px 0}
.result-actions{display:flex;gap:7px;justify-content:flex-end}
.dropzone{display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px dashed #cfdbc5;background:#fafcf6;border-radius:8px;height:105px;margin-bottom:11px;cursor:pointer;position:relative}
.dropzone:hover{background:#f5f9ee;border-color:#b5c9a5}
.dropzone input{position:absolute;inset:0;opacity:0;cursor:pointer}
.drop-ico{color:#8fa879;font-size:19px;margin-bottom:3px}
.dropzone b{font:600 9.5px var(--display);color:#60755f}
.dropzone small{font-size:7.5px;color:#a0aba0;margin-top:3px}
.add-modal .field{margin-bottom:9px}
.add-modal .control-row{padding:0;margin-bottom:9px}

/* ===== MOBILE NAV / RESPONSIVE ===== */
.mobile-nav{display:none}
@media(max-width:1080px){
  .app{grid-template-columns:205px minmax(0,1fr)}
  .sidebar{padding:22px 13px 14px}
  .views{padding:26px 24px 45px}
  .topbar{padding:0 24px}
  .stat-trend{display:none}
  .action-hint{display:none}
  .view-legend{display:none}
  .library-layout{grid-template-columns:minmax(0,1fr) 300px}
  .budget-grid{grid-template-columns:1fr 1.05fr}
  .process-layout{grid-template-columns:minmax(0,1fr) 285px}
}
@media(max-width:900px){
  .app{display:block}
  .sidebar{display:none}
  .topbar{height:57px;padding:0 17px}
  .views{padding:22px 17px 92px}
  .mobile-nav{display:flex;position:fixed;left:0;right:0;bottom:0;background:rgba(251,252,248,.96);backdrop-filter:blur(14px);border-top:1px solid var(--line);z-index:10;padding:6px 4px calc(6px + env(safe-area-inset-bottom))}
  .mobile-nav button{flex:1;border:0;background:none;display:flex;flex-direction:column;align-items:center;gap:2px;font:7px var(--sans);color:#94a095;padding:5px 1px}
  .mobile-nav button span{font-size:14px;font-family:var(--display)}
  .mobile-nav button.active{color:#34583e}
  .view-head{display:block;margin-bottom:20px}
  .view-head h1{font-size:34px;margin-top:10px}
  .lead{font-size:11px;max-width:100%}
  .head-actions{margin-top:15px;padding:0;flex-wrap:wrap}
  .head-actions .btn{flex:1;font-size:9.5px}
  .stat-strip{grid-template-columns:1fr 1fr;margin-bottom:13px}
  .stat:nth-child(2){border-right:0}
  .stat{border-bottom:1px solid var(--line-soft);padding:12px}
  .stat:nth-child(3),.stat:nth-child(4){border-bottom:0}
  .panel-hero-grid{grid-template-columns:1fr}
  .hero-grow{padding:18px 17px 0}
  .panel-columns,.panel-columns-wide{grid-template-columns:1fr}
  .oracle-card{padding:16px}
  .sim-statusbar{display:grid;grid-template-columns:1.1fr 1fr;padding:10px 13px;gap:9px}
  .sim-day{border-right:0;margin-right:0;padding-right:0;grid-row:span 2}
  .sim-status-item{border-right:0;padding:0}
  .sim-status-item.wide{grid-column:1/-1;text-align:left;border-top:1px solid var(--line-soft);padding-top:7px}
  .sim-grid{grid-template-columns:1fr}
  .sim-side{grid-template-columns:1fr 1fr}
  .sim-side .log-panel,.sim-side .goal-card{grid-column:1/-1}
  .greenhouse-scene{height:300px;margin:0 12px}
  .action-grid{grid-template-columns:repeat(3,1fr);padding:0 13px 12px}
  .action-card{height:58px}
  .advance-row{padding:10px 13px}
  .tip small{font-size:8px;max-width:200px}
  .sim-head .head-actions .btn{flex:0 1 auto}
  .library-stats{grid-template-columns:1fr 1fr;padding:0;margin-bottom:12px}
  .library-stats>div{padding:11px 13px;border-bottom:1px solid var(--line-soft)}
  .library-stats>div:nth-child(2n){border-right:0}
  .library-stats .lib-storage{grid-column:1/-1;border-bottom:0}
  .library-toolbar{flex-wrap:wrap}
  .search-field{flex-basis:100%}
  .select{flex:1;min-width:0}
  .toggle-btn{flex:1;justify-content:center}
  .dup-banner{align-items:flex-start}
  .dup-banner p{display:none}
  .dup-banner button{padding-top:2px}
  .library-layout{grid-template-columns:1fr}
  .resource-detail{position:static;display:none}
  .resource-detail.mobile-open{display:block;position:fixed;inset:auto 0 0 0;max-height:82vh;overflow:auto;border-radius:14px 14px 0 0;z-index:25;padding:20px;box-shadow:0 -10px 50px #17231d40;min-height:0}
  .resource-detail.mobile-open:before{content:'—';display:block;text-align:center;color:#c2ccc0;margin-top:-10px;margin-bottom:6px;position:sticky;top:-10px;background:#fff;padding:2px}
  .oracle-badge-large{display:none}
  .oracle-layout{grid-template-columns:1fr}
  .chat-card{height:calc(100vh - 250px);min-height:470px}
  .sources-card{position:static}
  .sources-list{min-height:0;max-height:220px;overflow:auto}
  .budget-grid{grid-template-columns:1fr}
  .budget-results{grid-template-columns:1fr}
  .process-summary{grid-template-columns:1fr 1fr;padding:0}
  .process-summary>div{padding:11px 13px;border-bottom:1px solid var(--line-soft)}
  .process-summary>div:nth-child(2n){border-right:0}
  .process-summary>div:nth-child(3),.process-summary>div:nth-child(4){border-bottom:0}
  .process-layout{grid-template-columns:1fr}
  .process-side{grid-template-columns:1fr;order:2}
  .process-timeline{order:1}
  .phase-block{padding-right:13px}
}
@media(max-width:520px){
  .topbar{padding:0 13px}
  .views{padding:18px 13px 88px}
  .crumb{font-size:7px}
  .legal-pill{display:none}
  .icon-btn{width:29px;height:29px}
  .view-head h1{font-size:29px}
  .lead{font-size:10.5px}
  .stat-strip{border-radius:8px}
  .stat{padding:10px 9px;gap:7px}
  .stat-ico{width:26px;height:26px;font-size:12px}
  .stat b{font-size:15px}
  .stat-label{font-size:6px}
  .hero-grow-foot{gap:15px}
  .hero-metric .bar{width:48px}
  .hero-grow h2{font-size:18px}
  .hero-mini{height:138px}
  .hero-mini-grid{left:20px;right:20px;gap:3px}
  .panel-columns{gap:12px}
  .action-grid{grid-template-columns:1fr 1fr;gap:6px}
  .action-card{height:55px}
  .advance-row{align-items:flex-end}
  .tip small{max-width:160px;font-size:7.5px}
  .advance-button{font-size:8px;padding:0 9px;gap:8px;height:32px}
  .sim-side{grid-template-columns:1fr}
  .sim-side .log-panel,.sim-side .goal-card{grid-column:auto}
  .sim-statusbar{grid-template-columns:1.2fr 1fr}
  .sim-status-item.wide{display:none}
  .greenhouse-scene{height:282px}
  .room{inset:27px 30px 26px}
  .grow-bed{left:5%;right:5%;padding:7px}
  .bed-grid{gap:4px}
  .plant-slot .plant{transform:scale(.82);transform-origin:bottom center}
  .plant-detail{gap:9px;padding:0 12px}
  .detail-stat:nth-of-type(3){display:none}
  .detail-bar{width:28px}
  .detail-note{display:none}
  .library-toolbar .select{font-size:8px}
  .search-field kbd{display:none}
  .lib-row{padding:10px 11px}
  .lib-title{font-size:9.5px;white-space:normal;line-height:1.3}
  .lib-row-side{display:none}
  .dup-banner{font-size:8px}
  .dup-banner button{display:none}
  .chat-card{height:calc(100vh - 220px);min-height:440px}
  .chat-log{padding:12px}
  .msg{max-width:94%}
  .chat-prompts{overflow-x:auto;flex-wrap:nowrap;padding-bottom:7px}
  .chat-prompts button{white-space:nowrap}
  .sources-card{display:none}
  .budget-big{font-size:38px}
  .budget-controls .control-row{padding:0 15px}
  .control-group{padding:0 15px}
  .assumption-note,.legal-scale{margin-left:15px;margin-right:15px}
  .budget-highlight{flex-wrap:wrap}
  .budget-sub{flex-wrap:wrap;gap:5px}
  .process-summary b{font-size:10.5px}
  .phase-block{grid-template-columns:47px 1fr}
  .phase-block:before{left:31px}
  .phase-marker span{width:24px;height:24px}
  .process-timeline{padding:3px 0}
  .phase-head{display:block}
  .phase-cost{text-align:left;margin:4px 0 6px}
  .footer-space{height:0}
  .modal{padding:23px 19px}
  .result-grid b{font-size:14px}
}

(() => {
  'use strict';
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const fmt = (n) => Math.round(n).toLocaleString('es-AR');
  const esc = (s) => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const norm = (s) => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  const STAGES = [
    { name: 'Plántula', from: 1, pill: 'PLÁNTULA' },
    { name: 'Crecimiento', from: 12, pill: 'CRECIMIENTO' },
    { name: 'Prefloración', from: 27, pill: 'PREFLORACIÓN' },
    { name: 'Floración', from: 37, pill: 'FLORACIÓN' },
    { name: 'Maduración', from: 57, pill: 'MADURACIÓN' },
    { name: 'Cosecha', from: 67, pill: 'COSECHA' }
  ];

  const initialGame = () => ({
    day: 1, selected: 0, water: 15, nutrients: 7, energy: 88, cash: 48000,
    temp: 24, humidity: 58, light: 18, vented: false, harvested: 0,
    harvestYield: 0, spent: 0, finished: false,
    plants: Array.from({ length: 9 }, (_, i) => ({
      id: i + 1, age: 1 + (i % 3), health: 88 + (i % 4) * 3,
      moisture: 46 + (i * 11) % 31, nutrition: 48 + (i * 7) % 28,
      alive: true, checked: false
    })),
    logs: [{ day: 1, text: '<b>Temporada iniciada.</b> Nueve autos en su primer día.', kind: 'success' }]
  });

  const initialBudget = () => ({ plants: 9, yield: 55, price: 4500, kwh: 95, hours: 18, days: 75, watts: 240 });
  const defaultApp = () => ({
    view: 'panel', budget: initialBudget(), tasks: {}, legal: {}, userResources: [],
    selectedResource: 3, queries: 0, chat: [], chatSources: [], dupOnly: false
  });

  let game, app;
  try {
    const saved = JSON.parse(localStorage.getItem('verde-app-v2') || 'null');
    game = saved && saved.game && Array.isArray(saved.game.plants) ? saved.game : initialGame();
    app = Object.assign(defaultApp(), saved ? saved.app : {});
    app.budget = Object.assign(initialBudget(), app.budget || {});
    app.userResources = Array.isArray(app.userResources) ? app.userResources : [];
  } catch { game = initialGame(); app = defaultApp(); }

  const persist = () => localStorage.setItem('verde-app-v2', JSON.stringify({ game, app }));

  /* ---------- derived data ---------- */
  const allResources = () => [...app.userResources, ...window.LIBRARY];
  const plantStage = (p) => [...STAGES].reverse().find(s => p.age >= s.from) || STAGES[0];
  const dayPhase = (d) => window.PHASES.find(p => d >= p.from && d <= p.to) || window.PHASES[window.PHASES.length - 1];
  const statusOf = (p) => !p.alive ? 'dead' : (p.health < 55 || p.moisture < 20 || p.moisture > 87 || p.nutrition < 16 ? 'attention' : '');
  const healthyCount = () => game.plants.filter(p => p.alive && p.health >= 50).length;
  const activeCount = () => game.plants.filter(p => p.alive).length;
  const readyPlants = () => game.plants.filter(p => p.alive && p.age >= 67);
  const avgHealth = () => {
    const alive = game.plants.filter(p => p.alive);
    return alive.length ? Math.round(alive.reduce((n, p) => n + p.health, 0) / alive.length) : 0;
  };
  const stageForDay = (d) => [...STAGES].reverse().find(s => d >= s.from) || STAGES[0];
  const nextStage = (d) => STAGES.find(s => s.from > d);

  function costsFor(b) {
    const energy = (b.watts / 1000) * b.hours * b.days * b.kwh;
    const seeds = b.plants * 8000;
    const substrate = b.plants * 7500;
    const nutrition = b.plants * 6000;
    const water = 1200 + b.plants * 140;
    const equipment = 120000 * Math.pow(b.plants / 9, 0.55);
    const misc = 22000 * Math.pow(b.plants / 9, 0.4);
    const management = b.plants * 2500;
    const subtotal = seeds + substrate + nutrition + energy + water + equipment + misc + management;
    const contingency = subtotal * 0.04;
    const total = subtotal + contingency;
    const grams = b.plants * b.yield;
    const value = grams * b.price;
    return {
      items: [
        { key: 'seeds', name: 'Semillas', value: seeds, color: '#3f6b4a' },
        { key: 'substrate', name: 'Sustrato', value: substrate, color: '#7f9b5e' },
        { key: 'nutrition', name: 'Nutrición', value: nutrition, color: '#b2bc70' },
        { key: 'energy', name: 'Energía', value: energy, color: '#d0ac65' },
        { key: 'equipment', name: 'Equipos', value: equipment, color: '#8e9d8d' },
        { key: 'water', name: 'Agua e insumos', value: water + misc, color: '#6f9590' },
        { key: 'management', name: 'Gestión', value: management, color: '#b3a58c' },
        { key: 'contingency', name: 'Contingencia', value: contingency, color: '#d8dfd2' }
      ],
      total, grams, value, energy, perPlant: total / b.plants,
      perGram: total / grams, margin: ((value - total) / total) * 100
    };
  }

  const budget = () => costsFor(app.budget);

  function scaleScenario(n) {
    const b = Object.assign({}, app.budget, { plants: n, watts: Math.max(120, app.budget.watts * n / 9) });
    const c = costsFor(b);
    return { cost: c.total, perGram: c.perGram, grams: c.grams };
  }

  /* ---------- render: shared ---------- */
  const VIEWS = { panel: 'PANEL', sim: 'SIMULADOR', library: 'BIBLIOTECA', oracle: 'ORÁCULO IA', budget: 'PRESUPUESTO', process: 'PROCESO' };
  function navigate(view, opts = {}) {
    if (!VIEWS[view]) view = 'panel';
    app.view = view;
    $$('.view').forEach(v => v.classList.toggle('active', v.id === `view-${view}`));
    $$('.nav-item,.mobile-nav button').forEach(b => b.classList.toggle('active', b.dataset.nav === view));
    $('#crumbCurrent').textContent = VIEWS[view];
    if (view === 'library') renderLibrary(opts.resourceId);
    if (view === 'oracle') { renderChat(); if (opts.question) askOracle(opts.question); else setTimeout(() => $('#chatInput')?.focus(), 250); }
    if (view === 'budget') renderBudget();
    if (view === 'process') renderProcess();
    if (view === 'panel') renderPanel();
    if (view === 'sim') renderSim();
    persist();
    history.replaceState(null, '', `#${view}`);
    window.scrollTo({ top: 0, behavior: 'instant' });
  }

  function renderNav() {
    $('#navDay').textContent = 'D' + String(game.day).padStart(2, '0');
    const docs = allResources().length;
    $('#navDocs').textContent = docs;
    $('#panelDay').textContent = String(game.day).padStart(2, '0');
    $('#statDocs').textContent = docs;
    $('#statPlants').textContent = activeCount();
    $('#statQueries').textContent = app.queries;
    $('#statBudget').textContent = fmt(budget().total);
    $('#navDocs').textContent = docs;
  }

  /* ---------- render: panel ---------- */
  function renderPanel() {
    renderNav();
    const phase = stageForDay(game.day);
    $('#panelPhase').textContent = phase.pill;
    $('#heroDay').textContent = String(game.day).padStart(2, '0');
    $('#heroPhase').textContent = phase.name;
    $('#heroHealth').textContent = avgHealth() + '%';
    $('#heroHealthBar').style.width = avgHealth() + '%';
    $('#heroDays').textContent = Math.max(0, 75 - game.day);
    $('#heroHarvest').textContent = game.harvested;
    const p = dayPhase(game.day);
    $('#heroInsight').textContent = game.finished
      ? `Temporada completada: ${fmt(game.harvestYield)} g registrados y ${game.harvested} cosechas. Revisá el resultado o iniciá una nueva temporada.`
      : phaseMessage();
    $('#focusStamp').textContent = 'D' + String(game.day).padStart(2, '0');

    $('#miniPlants').innerHTML = game.plants.map(p => {
      const st = statusOf(p);
      const h = 15 + Math.min(30, p.age * .55);
      return `<div class="mini-pot ${st}" title="Planta ${p.id}"><span class="mini-plant" style="--h:${h}px"></span></div>`;
    }).join('');

    const milestones = [
      { name: 'Plántula', from: 1 }, { name: 'Crecimiento', from: 12 }, { name: 'Floración', from: 27 },
      { name: 'Maduración', from: 57 }, { name: 'Cosecha', from: 67 }
    ];
    let current = 0;
    milestones.forEach((m, i) => { if (game.day >= m.from) current = i; });
    $('#seasonTrack').innerHTML = milestones.map((m, i) => {
      const next = milestones[i + 1];
      const cls = game.day >= (next ? next.from : 76) ? 'done' : i === current ? 'current' : '';
      return `<div class="season-node ${cls}"><span class="season-dot"></span><span class="sn-name">${m.name}</span><span class="sn-days">DÍA ${m.from}</span></div>`;
    }).join('');

    $('#focusList').innerHTML = p.tasks.slice(0, 3).map(t => `<div class="focus-item"><span>◆</span>${esc(t.text)}</div>`).join('');
    if (game.finished) $('#focusList').innerHTML = `<div class="focus-item"><span>◆</span>Cosecha registrada. Compará el costo real con tu presupuesto.</div><div class="focus-item"><span>◆</span>Guardá aprendizajes en la bitácora de la próxima temporada.</div><div class="focus-item"><span>◆</span>Revisá los recursos de secado y curado.</div>`;

    const recent = window.LIBRARY.slice(-3).reverse();
    $('#recentList').innerHTML = recent.map(r => `<div class="recent-item" data-resource="${r.id}"><span class="recent-icon">PDF</span><span class="recent-info"><span class="recent-title">${esc(r.title)}</span><span class="recent-meta">${esc(r.diploma)} · ${r.module}</span></span><span class="recent-tag">${r.pages} pp.</span></div>`).join('');
    $$('#recentList .recent-item').forEach(el => el.addEventListener('click', () => navigate('library', { resourceId: Number(el.dataset.resource) })));

    const dups = window.LIBRARY.filter(r => r.dup);
    const groups = [...new Set(dups.map(r => r.dup))];
    $('#dupCount').textContent = dups.length;
    $('#insightCount').textContent = groups.length;
    const pair = window.LIBRARY.filter(r => r.dup === 'riego').slice(0, 2);
    $('#insightPair').innerHTML = pair.map((r, i) => `<span class="pair-dot"></span><b>${esc(r.title)}</b>${i === 0 ? '<span style="font-size:7px;color:#b0bab0">↔</span>' : ''}`).join('');
  }

  function phaseMessage() {
    const selected = game.plants[game.selected] || game.plants[0];
    if (!selected.alive) return 'Una planta ya cerró su ciclo. El resto sigue avanzando: mantené la rutina y revisá la madurez del resto.';
    if (selected.moisture < 24) return 'El sustrato de la planta seleccionada está seco. Regá con moderación y volvé a observar el drenaje.';
    if (selected.moisture > 82) return 'La maceta todavía está húmeda. Esperá antes de regar: el exceso de agua también estresa.';
    return dayPhase(game.day).focus[0];
  }

  /* ---------- render: sim ---------- */
  function renderSim() {
    renderNav();
    const selected = game.plants[game.selected] || game.plants[0];
    $('#dayNumber').textContent = String(game.day).padStart(2, '0');
    $('#dateLabel').textContent = `${game.day < 15 ? '21 MAR' : game.day < 46 ? '15 ABR' : '20 MAY'} · 08:00`;
    $('#weekLabel').textContent = String(Math.ceil(game.day / 7)).padStart(2, '0');
    $('#harvestLabel').textContent = game.harvested;
    $('#spentLabel').textContent = '$' + fmt(game.spent);
    const next = nextStage(game.day);
    $('#milestoneLabel').textContent = next ? `Día ${next.from} · ${next.name}` : 'Cosecha y cierre';
    $('#phasePill').textContent = selected.alive ? plantStage(selected).pill : 'CICLO CERRADO';
    $('#tempValue').textContent = game.temp;
    $('#humidityValue').textContent = game.humidity;
    $('#lightValue').textContent = game.light;
    $('#waterValue').innerHTML = `${game.water} <small>/ 20 L</small>`;
    $('#nutrientValue').innerHTML = `${game.nutrients} <small>/ 10</small>`;
    $('#energyValue').innerHTML = `${game.energy} <small>/ 100</small>`;
    $('#waterMeter').style.width = `${game.water / 20 * 100}%`;
    $('#nutrientMeter').style.width = `${game.nutrients / 10 * 100}%`;
    $('#energyMeter').style.width = `${game.energy}%`;
    $('#readyCount').textContent = readyPlants().length;
    $('#selectedLabel').textContent = `Planta ${String(game.selected + 1).padStart(2, '0')}`;
    $('#goalProgress').style.width = `${Math.max(0, healthyCount() / 9 * 100)}%`;
    $('#goalLabel').textContent = `${healthyCount()} de 9 plantas activas`;
    $('#spentFoot').innerHTML = `$${fmt(game.spent)} <small>ARS</small>`;
    $('#cashValue').textContent = '$' + fmt(game.cash);

    const tempState = game.temp > 29 || game.temp < 19 ? ['ALERTA', 'bad'] : game.temp > 27 || game.temp < 21 ? ['OBSERVAR', 'warn'] : ['ÓPTIMA', 'good'];
    const humState = game.humidity > 72 || game.humidity < 35 ? ['OBSERVAR', 'warn'] : ['ÓPTIMA', 'good'];
    $('#tempState').textContent = tempState[0];
    $('#tempState').className = `reading-state ${tempState[1]}`;
    $('#humidityState').textContent = humState[0];
    $('#humidityState').className = `reading-state ${humState[1]}`;
    $('#sceneStatus').textContent = tempState[1] === 'bad' || humState[1] === 'warn' ? 'REVISAR CONDICIONES' : 'CONDICIONES ESTABLES';
    $('#climateNote').textContent = game.temp > 27 ? 'La temperatura subió. Ventilá para refrescar el ambiente.' : game.humidity > 72 ? 'Humedad elevada. Una buena ventilación ayuda.' : 'Ambiente estable. Mantené una rutina constante.';

    $('#plantGrid').innerHTML = game.plants.map((p, i) => {
      const status = statusOf(p);
      const grow = Math.min(75, 18 + p.age * .74);
      return `<button class="plant-slot ${status} ${p.age >= 37 ? 'bloom' : ''} ${i === game.selected ? 'selected' : ''}" data-plant="${i}" aria-label="Planta ${i + 1}, ${p.alive ? plantStage(p).name : 'cosechada'}"><span class="plant-id">${String(i + 1).padStart(2, '0')}</span><span class="plant-condition"></span>${p.alive ? `<span class="plant" style="--grow:${grow}"><i class="plant-stem"></i><i class="leaf l1"></i><i class="leaf l2"></i><i class="leaf l3"></i><i class="leaf l4"></i><i class="leaf l5"></i></span>` : '<span class="plant" style="--grow:10"><i class="plant-stem"></i></span>'}<span class="pot"></span></button>`;
    }).join('');
    $$('#plantGrid .plant-slot').forEach(el => el.addEventListener('click', () => { game.selected = Number(el.dataset.plant); renderSim(); persist(); }));

    if (!selected.alive) {
      $('#plantDetail').innerHTML = `<span class="detail-title">Planta ${String(game.selected + 1).padStart(2, '0')}<small>Ciclo completado</small></span><span class="detail-note">Buen trabajo: ya está en tu registro de cosecha.</span>`;
    } else {
      $('#plantDetail').innerHTML = `<span class="detail-title">Planta ${String(game.selected + 1).padStart(2, '0')}<small>${plantStage(selected).name} · Día ${selected.age}</small></span><span class="detail-stat">VITALIDAD <b>${selected.health}%</b><i class="detail-bar"><i style="width:${selected.health}%"></i></i></span><span class="detail-stat">HUMEDAD <b>${selected.moisture}%</b><i class="detail-bar"><i style="width:${selected.moisture}%"></i></i></span><span class="detail-note">${selected.checked ? 'Revisión al día ✓' : statusOf(selected) ? 'Necesita atención' : 'Todo en orden'}</span>`;
    }

    $$('.action-card').forEach(btn => {
      const action = btn.dataset.action;
      btn.disabled =
        (action === 'water' && (!selected.alive || game.water < 1 || selected.moisture > 82)) ||
        (action === 'feed' && (!selected.alive || game.nutrients < 1 || selected.nutrition > 88)) ||
        (action === 'vent' && (game.energy < 1 || game.vented)) ||
        (action === 'harvest' && (!selected.alive || selected.age < 67));
    });

    $('#logCount').textContent = String(game.logs.length).padStart(2, '0');
    $('#logList').innerHTML = game.logs.slice(0, 4).map(x => `<div class="log-item"><span class="log-mark ${x.kind}"></span><span class="log-time">D${String(x.day).padStart(2, '0')}</span><span class="log-text">${x.text}</span></div>`).join('');
    $('#tipText').textContent = !selected.alive ? 'Elegí una planta activa para continuar con los cuidados.'
      : selected.moisture < 30 ? 'El sustrato está seco. Una pequeña cantidad de agua puede ayudar.'
      : selected.moisture > 78 ? 'El sustrato sigue húmedo; esperá antes de volver a regar.'
      : selected.age >= 67 ? 'Esta planta alcanzó la madurez. Podés cosecharla.'
      : 'Revisá el sustrato antes de regar. Un exceso de agua también estresa.';
  }

  function saveAndRefresh() { persist(); renderSim(); renderPanel(); }

  function action(type) {
    const p = game.plants[game.selected];
    if (!p) return;
    if (type === 'water') {
      if (!p.alive || p.moisture > 82 || game.water < 1) return;
      p.moisture = Math.min(100, p.moisture + 45); game.water--; p.checked = true; game.spent += 150;
      log(`<b>Riego aplicado.</b> Planta ${p.id} · sustrato al ${p.moisture}%.`);
      showToast(`Planta ${p.id}: riego aplicado.`);
    }
    if (type === 'feed') {
      if (!p.alive || p.nutrition > 88 || game.nutrients < 1) return;
      p.nutrition = Math.min(100, p.nutrition + 42); game.nutrients--; p.checked = true; game.spent += 900;
      log(`<b>Nutrición equilibrada.</b> Planta ${p.id} recibió una dosis.`);
      showToast(`Planta ${p.id}: aporte aplicado.`);
    }
    if (type === 'inspect') {
      if (!p.alive) return;
      p.checked = true;
      const msg = p.moisture < 30 ? 'Sustrato seco' : p.moisture > 78 ? 'Humedad alta' : p.health < 60 ? 'Vitalidad baja' : 'Sin señales de estrés';
      log(`<b>Inspección · Planta ${p.id}.</b> ${msg}.`);
      showToast(`Planta ${p.id}: ${msg.toLowerCase()}.`);
    }
    if (type === 'vent') {
      if (game.energy < 1 || game.vented) return;
      game.energy--; game.temp = Math.max(19, game.temp - 3); game.humidity = Math.max(40, game.humidity - 8); game.vented = true; game.spent += 90;
      log('<b>Ventilación activada.</b> El ambiente se renovó.');
      showToast('Ambiente renovado.');
    }
    if (type === 'harvest') {
      if (!p.alive || p.age < 67) return;
      const grams = Math.round(10 + p.health * .55 + Math.min(8, (p.age - 67) * .4));
      p.alive = false; game.harvested++; game.harvestYield += grams; game.spent += 1200;
      const quality = p.health > 75 ? 'calidad excelente' : p.health > 50 ? 'calidad equilibrada' : 'calidad modesta';
      log(`<b>Planta ${p.id} cosechada.</b> ${grams} g · ${quality}.`, 'success');
      showToast(`¡${grams} g cosechados! ${quality}.`);
    }
    saveAndRefresh();
  }

  function log(text, kind = '') {
    game.logs.unshift({ day: game.day, text, kind });
    game.logs = game.logs.slice(0, 8);
  }

  function advance() {
    if (game.finished) { showToast('La temporada terminó. Podés reiniciar desde el resumen.'); return; }
    if (game.day >= 75) { game.finished = true; showToast('Día 75: temporada cerrada. Revisá tu cosecha.'); saveAndRefresh(); return; }
    game.day++; game.vented = false;
    game.temp = Math.max(18, Math.min(31, game.temp + (Math.random() < .32 ? (Math.random() < .5 ? -1 : 1) : 0)));
    game.humidity = Math.max(35, Math.min(78, game.humidity + (Math.random() < .5 ? -3 : 3)));
    game.energy = Math.max(0, game.energy - 2);
    game.spent += 4200 + Math.round(Math.random() * 600);
    game.plants.forEach(p => {
      if (!p.alive) return;
      p.age++; p.moisture = Math.max(0, p.moisture - 10 - Math.floor(Math.random() * 5)); p.nutrition = Math.max(0, p.nutrition - 2);
      let stress = 0;
      if (p.moisture < 18 || p.moisture > 92) stress += 7;
      if (p.nutrition < 12) stress += 5;
      if (game.temp > 29 || game.temp < 19) stress += 4;
      p.health = Math.max(0, Math.min(100, p.health + (stress ? -stress : 1)));
      p.checked = false;
      if (p.health <= 0) { p.alive = false; log(`<b>Planta ${p.id} completó su ciclo.</b> El estrés fue demasiado alto.`, 'warning'); }
    });
    if (game.day % 7 === 0) log(`<b>Semana ${Math.ceil(game.day / 7)}.</b> ${healthyCount()} plantas siguen saludables.`, healthyCount() >= 7 ? 'success' : 'warning');
    if (game.day === 27) log('<b>Prefloración:</b> ajustá nutrición y humedad para el estiramiento.', 'success');
    if (game.day === 67) log('<b>Ventana de cosecha abierta.</b> Revisá tricomas antes de cortar.', 'success');
    if (game.day >= 75) { game.finished = true; log(`<b>Temporada cerrada.</b> ${game.harvested} cosechas y ${fmt(game.harvestYield)} g registrados.`, 'success'); }
    saveAndRefresh();
    showToast(`Día ${game.day}: ${game.day >= 67 ? 'revisá la madurez de tus plantas.' : 'el cultivo ha crecido.'}`);
  }

  /* ---------- quick simulation ---------- */
  let quickStrategy = 'balanced';

  function runQuickSim() {
    let s = JSON.parse(JSON.stringify(game));
    const strategy = quickStrategy;
    const startDay = s.day;
    let water = s.water, nuts = s.nutrients, energy = s.energy;
    let extra = 0;
    const temp0 = s.temp, hum0 = s.humidity;

    while (s.day < 75) {
      s.day++;
      s.temp = Math.max(18, Math.min(31, s.temp + (Math.random() < .38 ? (Math.random() < .5 ? -1 : 1) : 0)));
      s.humidity = Math.max(35, Math.min(78, s.humidity + (Math.random() < .5 ? -3 : 3)));
      energy = Math.max(0, energy - 2);
      extra += strategy === 'intensive' ? 1600 : strategy === 'balanced' ? 650 : 250;
      s.plants.forEach(p => {
        if (!p.alive) return;
        p.age++;
        p.moisture = Math.max(0, p.moisture - 10 - Math.random() * 6);
        p.nutrition = Math.max(0, p.nutrition - 2.2);
        const waterAt = strategy === 'intensive' ? 55 : strategy === 'balanced' ? 38 : 24;
        const feedAt = strategy === 'intensive' ? 58 : strategy === 'balanced' ? 38 : 18;
        if (p.moisture < waterAt && water > 0) { p.moisture = Math.min(100, p.moisture + 44); water--; extra += 150; }
        if (p.nutrition < feedAt && nuts > 0) { p.nutrition = Math.min(100, p.nutrition + 42); nuts--; extra += 850; }
        let stress = 0;
        if (p.moisture < 18 || p.moisture > 92) stress += 7;
        if (p.nutrition < 12) stress += 5;
        if (s.temp > 29 || s.temp < 19) stress += 4;
        if (strategy === 'minimal') stress += 1;
        p.health = Math.max(0, Math.min(100, p.health + (stress ? -stress : 1)));
        if (p.health <= 0) p.alive = false;
      });
      if (water < 2) { water += 10; extra += 8000; }
      if (nuts < 1) { nuts += 5; extra += 12000; }
      if (energy < 10) { energy = 80; extra += 4000; }
      if ((s.temp > 27 || s.humidity > 69) && strategy !== 'minimal' && energy > 0 && Math.random() < .55) {
        s.temp -= 2; s.humidity -= 5; energy--; extra += 120;
      }
    }

    let grams = 0, alive = 0;
    s.plants.forEach(p => {
      if (!p.alive) return;
      alive++;
      const q = Math.max(.4, Math.min(1.1, p.health / 88));
      grams += Math.round(55 * q * (1 + Math.min(.06, (p.age - 67) * .002)));
    });

    s.water = water; s.nutrients = nuts; s.energy = energy;
    s.harvested += alive; s.harvestYield += grams;
    s.finished = true;
    s.spent += (75 - startDay) * 4300 + extra;
    s.temp = Math.max(18, Math.min(31, temp0 + (strategy === 'intensive' ? -1 : 0)));
    s.humidity = Math.max(35, Math.min(78, hum0 - (strategy === 'intensive' ? 4 : 2)));
    s.logs.unshift({ day: 75, text: `<b>Simulación veloz · ${strategy === 'balanced' ? 'equilibrada' : strategy === 'minimal' ? 'mínima' : 'intensiva'}.</b> ${grams} g registrados.`, kind: 'success' });
    if (s.logs.length > 8) s.logs = s.logs.slice(0, 8);
    game = s;

    const c = budget();
    const yieldG = game.harvestYield;
    const perGram = game.spent / Math.max(1, yieldG);
    $('#resultTitle').textContent = strategy === 'balanced' ? 'Una temporada equilibrada.' : strategy === 'minimal' ? 'Ahorraste, pero se notó.' : 'Control máximo, costo máximo.';
    $('#resultYield').textContent = fmt(grams) + ' g';
    $('#resultCost').textContent = '$' + fmt(game.spent);
    $('#resultPerGram').textContent = '$' + fmt(perGram);
    $('#resultHealthy').textContent = healthyCount() + ' / 9';
    $('#resultCopy').textContent = `Recorriste ${75 - startDay + 1} días en un instante. La simulación aplicó una rutina ${strategy === 'balanced' ? 'constante y reactiva' : strategy === 'minimal' ? 'de bajo insumo' : 'intensiva'} y resolvió los eventos del ciclo.`;
    const lessons = [];
    if (strategy === 'balanced') lessons.push('La rutina constante superó a las correcciones tardías: regar por necesidad evitó picos de estrés.');
    if (strategy === 'minimal') lessons.push('Ahorrar insumos redujo el costo operativo, pero el estrés hídrico y nutricional recortó el rendimiento.');
    if (strategy === 'intensive') lessons.push('Intervenir de más agregó costo y no garantizó mejor calidad: el rendimiento tiene un techo biológico.');
    lessons.push(healthyCount() >= 7 ? `Mantuviste ${healthyCount()} plantas saludables: cumpliste el objetivo de temporada.` : `Solo ${healthyCount()} plantas cerraron saludables. La próxima temporada, priorizá las alertas de humedad.`);
    lessons.push(`Costo por gramo simulado: $${fmt(perGram)} frente a un precio de referencia de $${fmt(app.budget.price)}/g.`);
    if (yieldG > 0) lessons.push(`Valor de referencia de la cosecha: $${fmt(yieldG * app.budget.price)}. En autocultivo no equivale a una autorización de venta.`);
    $('#resultLessons').innerHTML = lessons.map(x => `<div>${x}</div>`).join('');
    $('#quickModal').classList.remove('open');
    $('#resultModal').classList.add('open');
    persist(); renderSim(); renderPanel(); renderNav();
  }

